export function normalizeVal(v: unknown, ops?: string): unknown {
  if (!ops) return v; // normalization is opt-in: no ops -> value unchanged.
  // Ops are a comma list applied in written order (e.g. "trim,lower,date").
  const list = String(ops).split(',').map(s => s.trim()).filter(Boolean);
  const one = (x: unknown): unknown => {
    if (x == null) return x;
    let s: unknown = x;
    for (const op of list) {
      // Each op is type-guarded so it only touches values it understands.
      if (op === 'trim' && typeof s === 'string') s = s.trim();
      else if (op === 'lower' && typeof s === 'string') s = s.toLowerCase();
      else if (op === 'date') {
        const d = new Date(s as string);
        // Unparseable date -> keep the original, never emit "Invalid Date".
        s = isNaN(d.getTime()) ? s : d.toISOString().slice(0, 10);
      }
    }
    return s;
  };
  return Array.isArray(v) ? v.map(one) : one(v); // normalize lists element-wise.
}

export function compare(check: ReconCheck): ReconResult {
  // Normalize the mode; anything unrecognized falls through to 'exact'.
  const mode = (String(check.mode).toLowerCase() as CompareMode) || 'exact';
  const expected = normalizeVal(check.expected, opt.normalize);
  const actual = normalizeVal(check.actual, opt.normalize);
  // Every branch returns through done(): pass + a human-readable reason.
  const done = (pass: boolean, detail: string): ReconResult => ({ ...check, pass, detail });

  switch (mode) {
    case 'set': {
      const ok = setEq(tryJson(expected), tryJson(actual)); // order-insensitive membership.
      return done(ok, ok ? 'sets equal' : `set mismatch (exp ${display(expected)} / act ${display(actual)})`);
    }
    case 'exact':
    default: {
      // Canonical stringify both sides: structural equality regardless of formatting.
      const ok = JSON.stringify(tryJson(expected)) === JSON.stringify(tryJson(actual));
      return done(ok, ok ? 'equal' : `differ (exp ${display(expected)} / act ${display(actual)})`);
    }
  }
}

export function jsonPath(obj: unknown, pathExpr: string | null | undefined): unknown {
  if (pathExpr == null || pathExpr === '') return obj; // empty path -> whole object.
  // Rewrite [0]/[*] into .0/.* so a single split('.') handles both forms.
  const parts = String(pathExpr).replace(/\[(\d+|\*)\]/g, '.$1').split('.').filter(p => p !== '');
  // The frontier: a [*] segment fans out by pushing every array element.
  let cur: unknown[] = [obj]; // work on a frontier to support [*]
  for (const part of parts) {
    const next: unknown[] = [];
    for (const node of cur) {
      if (node == null) continue;
      // '*' fans out: push each element of an array node onto the next frontier.
      if (part === '*') { if (Array.isArray(node)) next.push(...node); }
      else next.push((node as Record<string, unknown>)[part]);
    }
    cur = next;
  }
  // [*] present -> return the whole list (for set/count); else unwrap to one value.
  return pathExpr.includes('[*]') ? cur : cur.length === 1 ? cur[0] : cur[0];
}

async query(sql: string, opts: QueryOptions = {}): Promise<QueryResult> {
  const inbox = path.join(this.bridgeDir, 'inbox');
  const outbox = path.join(this.bridgeDir, 'outbox');
  // Unique query id (timestamp + random) so concurrent queries never collide.
  const name = `q_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  fs.writeFileSync(path.join(inbox, name + '.sql'), sql, 'utf8'); // drop the SQL for the host helper.

  const deadline = Date.now() + (opts.timeoutSec ?? 300) * 1000; // default 5-minute bound.
  while (Date.now() < deadline) {
    await sleep(2000); // poll the outbox every 2s for the completion marker.
    const donePath = path.join(outbox, name + '.done');
    // The '.done' marker means the host wrote the result CSV and it's safe to read.
    if (fs.existsSync(donePath)) {
      const raw = fs.readFileSync(path.join(outbox, name + '.csv'), 'utf8');
      const rows = parseCsv(raw); // same CSV parser the offline demo showcases.
      return { rows, rowCount: rows.length, raw };
    }
  }
  // No marker before the deadline -> fail loudly rather than hang forever.
  throw new Error(`[db] bridge timeout waiting for ${name}`);
}

export function reconStep(result: ReconResult): EvidenceStep {
  const verdict: Verdict = result.pass ? 'pass' : 'fail'; // pass boolean -> the panel's colour.
  return {
    kind: 'db', // same EvidenceStep shape as API; only the kind differs.
    does: result.name,
    // Mode + expected in req, actual + reason in resp; both capped at 120 chars.
    req: `${result.mode}: expected=${display(result.expected, 120)}`,
    resp: `actual=${display(result.actual, 120)} — ${result.detail}`,
    verdict,
  };
}
